import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { parseBunLockfile, stripTrailingCommas } from "../src/lockfile/bun.ts";
import { parseNpmLockfile } from "../src/lockfile/npm.ts";
import { parsePnpmLockfile } from "../src/lockfile/pnpm.ts";
import type { ParsedLockfile } from "../src/lockfile/types.ts";
import { parseYarnLockfile } from "../src/lockfile/yarn.ts";
import { parseYamlDocuments } from "../src/lockfile/yaml.ts";

// Lockfiles generated by the real package managers (npm 11, pnpm 10, yarn 4, yarn 1.22, bun 1.3)
// for the same manifest. Every parser must agree on what is installed and how.
const read = (p: string) => readFileSync(new URL(`./fixtures/real/${p}`, import.meta.url), "utf8");
const manifest = JSON.parse(read("manifest.fixture.json"));

const EXPECTED = [
  "axios@0.21.0 direct prod",
  "follow-redirects@1.16.3 transitive prod",
  "js-tokens@4.0.0 transitive prod",
  "left-pad@1.3.0 direct prod", // installed through the alias my-pad
  "lodash@4.17.20 direct prod",
  "loose-envify@1.4.0 transitive prod",
  "minimist@0.0.8 transitive dev", // via mkdirp
  "minimist@1.2.5 direct dev",
  "mkdirp@0.5.1 direct dev",
  "react-dom@18.2.0 direct prod",
  "react@18.2.0 direct prod",
  "scheduler@0.23.2 transitive prod",
];

const summary = (r: ParsedLockfile) =>
  r.deps.map((d) => `${d.name}@${d.version} ${d.direct ? "direct" : "transitive"} ${d.dev ? "dev" : "prod"}`).sort();

const cases: Array<[string, () => ParsedLockfile]> = [
  ["npm (package-lock v3)", () => parseNpmLockfile(read("npm/lockfile.fixture.json"), manifest)],
  ["pnpm (lockfile v9)", () => parsePnpmLockfile(read("pnpm/lockfile.fixture.yaml"), manifest)],
  ["yarn berry (v4)", () => parseYarnLockfile(read("yarn-berry/lockfile.fixture.lock"), manifest)],
  ["yarn classic (v1)", () => parseYarnLockfile(read("yarn-classic/lockfile.fixture.lock"), manifest)],
  ["bun (bun.lock)", () => parseBunLockfile(read("bun/lockfile.fixture.jsonc"), manifest)],
];

for (const [label, parse] of cases) {
  test(`${label}: same packages, direct/transitive and dev/prod as every other manager`, () => {
    const r = parse();
    assert.deepEqual(summary(r), [...EXPECTED].sort());
  });
}

test("pnpm v6 and v5 key formats", () => {
  const v6 = `lockfileVersion: '6.0'
dependencies:
  lodash:
    specifier: ^4.17.0
    version: 4.17.20
  my-pad:
    specifier: npm:left-pad@1.3.0
    version: /left-pad@1.3.0
devDependencies:
  '@types/node':
    specifier: ^20
    version: 20.1.0
packages:
  /lodash@4.17.20:
    resolution: {integrity: sha512-x}
    dev: false
  /left-pad@1.3.0:
    resolution: {integrity: sha512-x}
    dev: false
  /@types/node@20.1.0:
    resolution: {integrity: sha512-x}
    dev: true
  /react-dom@18.2.0(react@18.2.0):
    resolution: {integrity: sha512-x}
    dev: false
  github.com/user/repo/abc123:
    resolution: {tarball: https://codeload.github.com/user/repo/tar.gz/abc123}
    dev: false
`;
  assert.deepEqual(summary(parsePnpmLockfile(v6)), [
    "@types/node@20.1.0 direct dev",
    "left-pad@1.3.0 direct prod",
    "lodash@4.17.20 direct prod",
    "react-dom@18.2.0 transitive prod",
  ]);
  const v5 = `lockfileVersion: 5.4
specifiers:
  lodash: ^4.17.0
dependencies:
  lodash: 4.17.20
packages:
  /lodash/4.17.20:
    resolution: {integrity: sha512-x}
    dev: false
  /@babel/core/7.24.0_react@18.2.0:
    resolution: {integrity: sha512-x}
    dev: true
`;
  assert.deepEqual(summary(parsePnpmLockfile(v5)), ["@babel/core@7.24.0 transitive dev", "lodash@4.17.20 direct prod"]);
});

test("yarn classic skips git/file/github deps", () => {
  const lock = `# yarn lockfile v1

lodash@^4.17.20:
  version "4.17.20"
  resolved "https://registry.yarnpkg.com/lodash/-/lodash-4.17.20.tgz"

"mylib@github:user/mylib":
  version "1.0.0"
  resolved "https://codeload.github.com/user/mylib/tar.gz/abc"

local@file:../local:
  version "1.0.0"
`;
  const r = parseYarnLockfile(lock, { dependencies: { lodash: "^4.17.20", mylib: "github:user/mylib", local: "file:../local" } });
  assert.deepEqual(summary(r), ["lodash@4.17.20 direct prod"]);
  assert.equal(r.skipped, 2);
});

test("YAML subset: prototype-safe keys, quotes, depth limit", () => {
  const [doc] = parseYamlDocuments(`__proto__:\n  polluted: yes\n'it''s': "a\\"b"\nflow: {a: 1}\n`);
  assert.equal(({} as Record<string, unknown>).polluted, undefined);
  assert.equal((doc!.__proto__ as unknown as Record<string, string>).polluted, "yes");
  assert.equal(doc!["it's"], 'a"b');
  assert.equal(doc!.flow, "{a: 1}");
  const deep = Array.from({ length: 100 }, (_, i) => `${" ".repeat(i * 2)}k${i}:`).join("\n");
  assert.throws(() => parseYamlDocuments(deep), /too deep/);
});

test("bun JSONC: trailing commas removed only outside strings", () => {
  assert.deepEqual(JSON.parse(stripTrailingCommas('{"a": [1, 2,], "b": "x,}",}')), { a: [1, 2], b: "x,}" });
});
